document.addEventListener("DOMContentLoaded",()=>{const banner=document.querySelector(".pdf-ink-banner");if(banner){const dismissBtn=banner.querySelector(".notice-dismiss");dismissBtn?.addEventListener("click",e=>{e.preventDefault();fetch(pdfInkSettings.ajaxUrl,{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded"},body:new URLSearchParams({action:"pdfink_lite_dismiss_banner",nonce:pdfInkSettings.nonce,duration:7})});banner.remove()})}});